def design(feats) -> Design:
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); types = list(feats.types)
    if not p or n < 10 or np.unique(y).size < 2 or MAX_DRIVERS < 1:
        return Design(drivers=(), columns=(), products=(), loadings={})
    labs = list(dict.fromkeys(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.asarray([s == l for s in feats.stratum], float) for l in labs[1:]])
    R = np.nan_to_num(np.atleast_2d(np.corrcoef(X, rowvar=False)))
    def fit(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(40):
            pr = 1 / (1 + np.exp(-np.clip(Z @ b, -30, 30)))
            H = Z.T @ (Z * (pr * (1 - pr))[:, None]) + 1e-6 * np.eye(Z.shape[1])
            st = np.linalg.solve(H, Z.T @ (y - pr)); st /= max(1, np.max(np.abs(st)) / 3); b += st
            if np.abs(st).max() < 1e-7: break
        pr = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(pr) + (1 - y) * np.log(1 - pr))), pr
    def ll(Z): return fit(Z)[0]
    def col(t): return X[:, t[0]] * X[:, t[1]] if isinstance(t, tuple) else X[:, t]
    def mk(terms): return np.column_stack([S] + [col(t) for t in terms])
    deg = (np.abs(R) >= 0.6).sum(0) - 1
    hubs = []
    for j in np.argsort(-deg):
        if types[j] in ('clinical', 'cohort') and deg[j] >= 3 and all(abs(R[j, h]) < 0.85 for h in hubs): hubs.append(j)
        if len(hubs) >= 3: break
    def gain(j, sel):
        base = list(sel) + [h for h in hubs if h != j and h not in sel]
        return max(0, 2 * (ll(mk(base + [j])) - ll(mk(base))))
    TW = 0.85; sel = []
    for k in range(MAX_DRIVERS):
        cand = [j for j in range(p) if j not in sel and j not in hubs and all(abs(R[j, s]) < TW for s in sel)]
        if not cand: break
        g = [gain(j, sel) for j in cand]; b = int(np.argmax(g))
        if stats.chi2.sf(g[b], 1) > 0.1 / p: break
        j = cand[b]; cl = [m for m in cand if abs(R[j, m]) >= 0.6]
        if len(cl) > 1:
            gm = {m: g[cand.index(m)] for m in cl}; ok = [m for m in gm if gm[m] >= g[b] - 2]
            j = min(ok, key=lambda m: sum(gain(o, sel + [m]) for o in ok if o != m))
        sel.append(j)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            if stats.chi2.sf(gain(j, [s for s in sel if s != j]), 1) > 0.05 / p:
                sel.remove(j); changed = True; break
    for h in hubs:
        C = [m for m in range(p) if (m == h or abs(R[h, m]) >= TW) and m not in sel and all(abs(R[m, s]) < TW for s in sel)]
        if h not in C: continue
        base = sel + [v for v in hubs if v != h and v not in sel]
        l0 = ll(mk(base)); gs = {m: 2 * (ll(mk(base + [m])) - l0) for m in C}
        m = max(gs, key=gs.get); m = m if gs[m] > gs[h] + 6 else h
        if stats.chi2.sf(gs[m], 1) < 0.05 / p: sel.append(m)
    sel.sort(key=lambda j: -gain(j, [s for s in sel if s != j]))
    base = sel + [h for h in hubs if h not in sel]; prods = []
    pairs = [(i, j) for i in range(p) for j in range(i, p)]
    r0 = y - fit(mk(base))[1]
    sc = np.array([abs(np.dot(col(pr) - col(pr).mean(), r0)) / (np.std(col(pr)) + 1e-9) for pr in pairs])
    cand = []
    for idx in np.argsort(-sc)[:20]:
        i, j = pairs[idx]; mains = list(dict.fromkeys(base + [i, j]))
        pv = stats.chi2.sf(max(0, 2 * (ll(mk(mains + [(i, j)])) - ll(mk(mains)))), 1)
        if pv < 0.005 / len(pairs): cand.append((pv, i, j))
    for pv, i, j in sorted(cand):
        if all(not ((abs(R[i, a]) >= 0.9 and abs(R[j, b]) >= 0.9) or (abs(R[i, b]) >= 0.9 and abs(R[j, a]) >= 0.9)) for a, b in prods): prods.append((i, j))
        if len(prods) >= 2: break
    drivers = list(sel)
    for i, j in prods:
        for m in (i, j):
            if all(abs(R[m, d]) < 0.9 for d in drivers): drivers.append(m)
    if not drivers: return Design(drivers=(), columns=(), products=(), loadings={})
    cols = list(dict.fromkeys(sel + [m for pr in prods for m in pr] + hubs))
    return Design(drivers=tuple(ids[m] for m in drivers[:MAX_DRIVERS]), columns=tuple(ids[m] for m in cols),
                  products=tuple((ids[i], ids[j]) for i, j in prods), loadings={})

